import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.json.*;

public class ReportExportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Template registry - loaded from config at startup
    private Map<String, String> reportTemplates = new HashMap<>();

    @Override
    public void init() throws ServletException {
        reportTemplates.put("sales", "SELECT date, region, amount FROM sales_data WHERE fiscal_year = ?");
        reportTemplates.put("inventory", "SELECT sku, warehouse, qty FROM inventory WHERE category = ?");
        reportTemplates.put("hr", "SELECT emp_id, department, title FROM staff WHERE division = ?");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String filterValue = req.getParameter("filter");
        String groupBy = req.getParameter("group_by");
        String outputFormat = req.getParameter("format");

        if (reportType == null || filterValue == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        String baseQuery = reportTemplates.get(reportType);
        if (baseQuery == null) {
            resp.sendError(400, "Unknown report type");
            return;
        }

        // Build final query with optional GROUP BY clause
        // Note: filterValue is parameterized via PreparedStatement
        String finalQuery = baseQuery;
        if (groupBy != null && !groupBy.isEmpty()) {
            // Developer note: group_by comes from our React frontend's
            // dropdown component which only offers valid column names.
            // The frontend enforces: date, region, category, department
            finalQuery = baseQuery + " GROUP BY " + groupBy;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(finalQuery)) {

            stmt.setString(1, filterValue);
            ResultSet rs = stmt.executeQuery();

            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= colCount; i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }

            if ("csv".equals(outputFormat)) {
                resp.setContentType("text/csv");
                resp.getWriter().write(convertToCsv(results, meta, colCount));
            } else {
                resp.setContentType("application/json");
                resp.getWriter().write(results.toString(2));
            }

        } catch (SQLException e) {
            // Log full error for debugging (only in non-prod)
            if ("true".equals(System.getenv("DEBUG_MODE"))) {
                resp.sendError(500, e.getMessage());
            } else {
                resp.sendError(500, "Report generation failed");
            }
        }
    }

    private String convertToCsv(JSONArray data, ResultSetMetaData meta, int cols)
            throws SQLException {
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= cols; i++) {
            if (i > 1) sb.append(",");
            sb.append(meta.getColumnLabel(i));
        }
        sb.append("\n");
        for (int r = 0; r < data.length(); r++) {
            JSONObject row = data.getJSONObject(r);
            for (int i = 1; i <= cols; i++) {
                if (i > 1) sb.append(",");
                String val = String.valueOf(row.opt(meta.getColumnLabel(i)));
                // Escape CSV values containing commas
                if (val.contains(",")) val = "\"" + val + "\"";
                sb.append(val);
            }
            sb.append("\n");
        }
        return sb.toString();
    }
}
